using System.ComponentModel.DataAnnotations;
using System.Text.Json.Serialization;
using Adyen.Models.Enums;

namespace Adyen.Models;

public record SecureRemoteCommerceCheckoutData
{
    /// <summary>
    /// The Secure Remote Commerce checkout payload to process the payment with.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("checkoutPayload")]
    [MaxLength(10000)]
    public string? CheckoutPayload { get; init; }

    /// <summary>
    /// This is the unique identifier generated by SRC system to track and link SRC messages. Available within the present checkout session (e.g. received in an earlier API response during the present session).
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("correlationId")]
    [StringLength(40, MinimumLength = 1)]
    public string? CorrelationId { get; init; }

    /// <summary>
    /// The <see href="https://docs.adyen.com/get-started-with-adyen/payment-glossary/#card-security-code-cvc-cvv-cid">card verification code</see>.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("cvc")]
    [StringLength(20, MinimumLength = 1)]
    public string? Cvc { get; init; }

    /// <summary>
    /// A unique identifier that represents the token associated with a card enrolled. Required for scheme 'mc'.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("digitalCardId")]
    [MaxLength(80)]
    public string? DigitalCardId { get; init; }

    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("scheme")]
    public Scheme? Scheme { get; init; }

    /// <summary>
    /// A unique identifier that represents the token associated with a card enrolled. Required for scheme 'visa'.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("tokenReference")]
    [MaxLength(80)]
    public string? TokenReference { get; init; }
}
